use crate::token::Token;

pub fn login(raw: &str, now: u64) -> Result<String, String> {
    let token = Token::verify(raw, now)?;
    Ok(format!("session:{}", token.raw))
}

use crate::token::Token;

pub fn bind(raw: &str, now: u64) -> Result<Token, String> {
    Token::verify(raw, now)
}

use crate::auth;
use crate::session;

pub fn test_login_ok() {
    assert!(auth::login("abc").is_ok());
}

pub fn test_bind_ok() {
    assert!(session::bind("abc").is_ok());
}

pub fn test_expired_is_string_error() {
    let result: Result<_, String> = crate::token::Token::verify("abc", 10000);
    match result {
        Err(error) => assert_eq!(error, "expired"),
        Ok(_) => panic!("expected expired token error"),
    }
}

pub fn test_session_does_not_persist_expired_token() {
    match session::bind("abc", 10000) {
        Err(error) => assert_eq!(error, "expired"),
        Ok(_) => panic!("expired token was persisted"),
    }
}

pub struct Token {
    pub raw: String,
    pub expires_at: u64,
}

impl Token {
    pub fn verify(raw: &str, now: u64) -> Result<Self, String> {
        if raw.is_empty() {
            return Err("empty".into());
        }

        let token = Self {
            raw: raw.to_string(),
            expires_at: 9999,
        };
        if token.expires_at < now {
            return Err("expired".into());
        }

        Ok(token)
    }
}
